def _skip_ws(text, n, i):
    while i < n:
        c = text[i]
        if c == ' ' or c == '\t' or c == '\n' or c == '\r':
            i += 1
        else:
            break
    return i


def _parse_hex4(text, n, pos):
    if pos + 4 > n:
        return -1
    v = 0
    for k in range(pos, pos + 4):
        c = text[k]
        if '0' <= c <= '9':
            d = ord(c) - 48
        elif 'a' <= c <= 'f':
            d = ord(c) - 87
        elif 'A' <= c <= 'F':
            d = ord(c) - 55
        else:
            return -1
        v = (v << 4) | d
    return v


def _parse_string(text, n, pos):
    if pos >= n or text[pos] != '"':
        raise ValueError
    pos += 1
    parts = []
    start = pos

    while True:
        if pos >= n:
            raise ValueError

        c = text[pos]

        if c == '"':
            if start < pos:
                parts.append(text[start:pos])
            return ''.join(parts), pos + 1

        if c == '\\':
            if start < pos:
                parts.append(text[start:pos])

            pos += 1
